<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../includes/functions.php'; require_login();
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = $_POST['action'] ?? ''; $id = filter_input(INPUT_POST, 'category_id', FILTER_VALIDATE_INT);
    $name = trim((string) ($_POST['category_name'] ?? '')); $description = trim((string) ($_POST['description'] ?? ''));
    try {
        if ($action === 'save') { if ($name === '') throw new InvalidArgumentException('Category name is required.'); if ($id) { $s = $pdo->prepare('UPDATE categories SET category_name = ?, description = ? WHERE category_id = ?'); $s->execute([$name, $description, $id]); flash('success', 'Category updated successfully.'); } else { $s = $pdo->prepare('INSERT INTO categories (category_name, description) VALUES (?, ?)'); $s->execute([$name, $description]); flash('success', 'Category added successfully.'); } }
        elseif ($action === 'delete' && $id) { $s = $pdo->prepare('DELETE FROM categories WHERE category_id = ?'); $s->execute([$id]); flash('success', 'Category deleted successfully.'); }
        redirect('/event_shit/categories/categories.php');
    } catch (InvalidArgumentException|PDOException $exception) { $error = $exception instanceof InvalidArgumentException ? $exception->getMessage() : 'Unable to complete the category operation.'; }
}
$search = trim((string) ($_GET['search'] ?? '')); $s = $pdo->prepare('SELECT * FROM categories WHERE category_name LIKE ? ORDER BY category_name'); $s->execute(['%' . $search . '%']); $categories = $s->fetchAll();
$pageTitle = 'Categories'; require __DIR__ . '/../includes/header.php'; require __DIR__ . '/../includes/sidebar.php';
?>
<main class="col-md-9 col-lg-10 p-4"><?php require __DIR__ . '/../includes/alerts.php'; ?><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="h3">Categories</h1><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#categoryModal">+ Add category</button></div>
<form class="row g-2 mb-3"><div class="col-sm-6"><input class="form-control" name="search" value="<?= e($search) ?>" placeholder="Search category name"></div><div class="col-auto"><button class="btn btn-outline-secondary">Search</button></div></form>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>ID</th><th>Category name</th><th>Description</th><th>Created</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($categories as $category): ?><tr><td><?= (int) $category['category_id'] ?></td><td><?= e($category['category_name']) ?></td><td><?= e($category['description']) ?></td><td><?= e($category['created_at']) ?></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#categoryModal" data-id="<?= (int) $category['category_id'] ?>" data-name="<?= e($category['category_name']) ?>" data-description="<?= e($category['description']) ?>">Edit</button><button class="btn btn-sm btn-outline-danger" data-bs-toggle="modal" data-bs-target="#deleteModal" data-id="<?= (int) $category['category_id'] ?>" data-name="<?= e($category['category_name']) ?>">Delete</button></td></tr><?php endforeach; ?><?php if (!$categories): ?><tr><td colspan="5" class="text-center text-secondary py-4">No categories found.</td></tr><?php endif; ?></tbody></table></div></div></main>
<div class="modal fade" id="categoryModal" tabindex="-1"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Category</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="category_id" id="category_id"><label class="form-label">Category name</label><input class="form-control mb-3" name="category_name" id="category_name" required><label class="form-label">Description</label><textarea class="form-control" name="description" id="category_description" rows="3"></textarea></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div>
<div class="modal fade" id="deleteModal" tabindex="-1"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Confirm delete</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body">Delete <strong id="delete_name"></strong>? This action cannot be undone.<input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="category_id" id="delete_id"></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal" type="button">Cancel</button><button class="btn btn-danger">Delete</button></div></form></div></div>
<script>document.getElementById('categoryModal').addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;document.getElementById('category_id').value=b.dataset.id||'';document.getElementById('category_name').value=b.dataset.name||'';document.getElementById('category_description').value=b.dataset.description||''});document.getElementById('deleteModal').addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;document.getElementById('delete_id').value=b.dataset.id;document.getElementById('delete_name').textContent=b.dataset.name});</script><?php require __DIR__ . '/../includes/footer.php'; ?>
